(()=>{if(!('serviceWorker'in navigator)||!isSecureContext||location.protocol==='file:')return;addEventListener('load',async()=>{try{const r=await navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'});function offer(w){if(!w||document.querySelector('.ss-update'))return;const box=document.createElement('section');box.className='ss-update';box.setAttribute('aria-label','網站更新');box.innerHTML='<p>有新版可用。請先儲存編輯再更新；未儲存的編輯會遺失。</p><button class="ss-link">儲存完成，更新</button><button class="ss-link">稍後</button>';const b=box.querySelectorAll('button');b[0].onclick=()=>{navigator.serviceWorker.addEventListener('controllerchange',()=>location.reload(),{once:true});w.postMessage({type:'ACTIVATE_UPDATE'});b[0].disabled=true};b[1].onclick=()=>box.remove();document.body.append(box)}if(r.waiting&&navigator.serviceWorker.controller)offer(r.waiting);r.addEventListener('updatefound',()=>{const w=r.installing;w?.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)offer(r.waiting||w)})});r.update().catch(()=>{})}catch(e){console.warn('Offline cache unavailable; online site remains usable',e)}})})();